const isNeighbor = (a: Cell, b: Cell): boolean =>
  !(a[0] === b[0] && a[1] === b[1]) &&
  Math.abs(a[0] - b[0]) <= 1 &&
  Math.abs(a[1] - b[1]) <= 1;

export const nextGeneration = (livingCells: Cell[]): Cell[] =>
  livingCells.filter(
    (cell) => livingCells.filter((other) => isNeighbor(cell, other)).length === 3,
  );
